describe('Sidebar Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's base URL
    });

    it('should expand the sidebar when clicked', () => {
        cy.get('.sidebar-toggle').click(); // Adjust the selector to your sidebar toggle button
        cy.get('.sidebar').should('be.visible'); // Adjust the selector to your sidebar
    });

    it('should collapse the sidebar when clicked again', () => {
        cy.get('.sidebar-toggle').click(); // Expand the sidebar first
        cy.get('.sidebar').should('be.visible'); // Ensure it's visible
        cy.get('.sidebar-toggle').click(); // Click to collapse
        cy.get('.sidebar').should('not.be.visible'); // Ensure it's not visible
    });
});
